-- Enxert.DB -- registros da literatura (5 fontes abertas).
-- Gerado a partir da planilha registros_enxertia.xlsx. Pode ser executado varias vezes.
-- Plantas e combinacoes sao referidas pelo NOME CIENTIFICO (nao por ID), para nao
-- colidir com plantas que a equipe ja tenha cadastrado.
-- conferido = 0: o trecho ainda nao foi conferido no PDF por uma pessoa.
-- TaxID fica NULL: use a opcao 7 do menu para preencher pelo NCBI.
-- Os nomes cientificos de cultivares e hibridos seguem a convencao do catalogo
-- (especie + cultivar entre parenteses) e sao mapeamento da equipe, nao da fonte.

INSERT OR IGNORE INTO Fontes (id_fonte, referencia, url) VALUES (1, 'Oliveira, E. R. M. et al. Incompatibilidade de combinações copa e porta-enxerto de citros. Embrapa Mandioca e Fruticultura / UFRB (avaliação em out/2011; o texto lido não informa o ano de publicação).', 'https://www.alice.cnptia.embrapa.br/alice/bitstream/doc/943732/1/INCOMPATIBILIDADEDECOMBINACOESCOPA4Y6G.pdf');
INSERT OR IGNORE INTO Fontes (id_fonte, referencia, url) VALUES (2, 'Oliveira, E. R. M. et al. Incompatibilidade de laranjeira doce ''Pera CNPMF D-6'' enxertada em onze porta-enxertos. 5ª Jornada Científica, Embrapa Mandioca e Fruticultura, 2011.', 'https://www.alice.cnptia.embrapa.br/alice/bitstream/doc/918527/1/IncompatibilidadelaranjeiraWALTERSOARESFILHO10911.pdf');
INSERT OR IGNORE INTO Fontes (id_fonte, referencia, url) VALUES (3, 'Mendonça, J. L.; Lopes, C. A.; Moita, A. W. Compatibilidade de enxertia de híbridos interespecíficos de Solanum com tomateiro visando controle de patógenos de solo. Savannah Journal of Research and Development, v.1, n.1, p.34-38, 2017 (Embrapa Hortaliças).', 'https://www.alice.cnptia.embrapa.br/alice/bitstream/doc/1078979/1/MENDONCAelalCompatibilidadedeenxertiadehibridosinterespecificos...Savannahv1n1p3438fev2017.pdf');
INSERT OR IGNORE INTO Fontes (id_fonte, referencia, url) VALUES (4, 'Elkins, R.; Bell, R.; Einhorn, T. Needs assessment for future US pear rootstock research directions based on the current state of pear production and rootstock research. Journal of the American Pomological Society, 66(3):153-163, 2012.', 'https://journal.americanpomological.org/index.php/jofaps/article/download/2800/2804/5959');
INSERT OR IGNORE INTO Fontes (id_fonte, referencia, url) VALUES (5, 'Yetişir, H.; Sarı, N. Effect of hypocotyl morphology on survival rate and growth of watermelon seedlings grafted on rootstocks with different emergence performance at various temperatures. Turkish Journal of Agriculture and Forestry, 28:231-237, 2004.', 'https://aj.tubitak.gov.tr/agriculture/issues/tar-04-28-4/tar-28-4-3-0309-1.pdf');

